insert into events (id, name, category, division, icon, tagline, description, venue, event_date, event_time, team_size, fee, rules, schedule, sort_order) values ('fine-arts', 'Fine Arts', 'Cultural', 'Open', 'palette', 'Express imagination through art and creativity.', 'A celebration of visual creativity where artists bring blank canvases to life. Participants showcase their skills across painting, sketching, and mixed media in a live competition setting.', 'Art Block, Room 101', '15 OCT 2026', '10:00 AM', 'Individual', '₹150', '["Participants must bring their own art materials.","Time limit: 3 hours per round.","Themes will be announced on the spot.","Judges decision will be final."]'::jsonb, '[{"time":"10:00 AM","activity":"Reporting & Material Setup"},{"time":"10:30 AM","activity":"Round 1 — Live Painting"},{"time":"01:00 PM","activity":"Lunch Break"},{"time":"02:00 PM","activity":"Round 2 — Sketching"},{"time":"04:00 PM","activity":"Results Announcement"}]'::jsonb, 0);
insert into events (id, name, category, division, icon, tagline, description, venue, event_date, event_time, team_size, fee, rules, schedule, sort_order) values ('music-solo', 'Music — Solo', 'Cultural', 'Music & Band', 'mic', 'A single voice. A single instrument. Pure magic.', 'Solo performers take the stage to showcase their vocal or instrumental talent. From classical ragas to contemporary hits, this is where individual brilliance shines.', 'Main Auditorium', '15 OCT 2026', '11:00 AM', 'Individual', '₹200', '["Time limit: 5 minutes per performance.","Backing tracks allowed; no lip-syncing.","Participants must bring their own instruments.","Original compositions are encouraged."]'::jsonb, '[{"time":"11:00 AM","activity":"Reporting & Sound Check"},{"time":"11:30 AM","activity":"Performance Round 1"},{"time":"01:00 PM","activity":"Lunch Break"},{"time":"02:00 PM","activity":"Final Round"},{"time":"04:00 PM","activity":"Results"}]'::jsonb, 1);
insert into events (id, name, category, division, icon, tagline, description, venue, event_date, event_time, team_size, fee, rules, schedule, sort_order) values ('music-group', 'Music — Group', 'Cultural', 'Music & Band', 'music', 'When voices and instruments unite, the stage comes alive.', 'Bands and musical groups perform together, blending vocals, guitars, drums, and more. A high-energy showcase of collaborative musical talent.', 'Main Auditorium', '16 OCT 2026', '10:00 AM', '3–8 Members', '₹800', '["Time limit: 8 minutes per performance.","Each group must have a minimum of 3 members.","Own instruments required; sound system provided.","No pre-recorded vocals allowed."]'::jsonb, '[{"time":"10:00 AM","activity":"Reporting & Setup"},{"time":"10:30 AM","activity":"Preliminary Round"},{"time":"01:00 PM","activity":"Lunch Break"},{"time":"02:00 PM","activity":"Final Round"},{"time":"05:00 PM","activity":"Results"}]'::jsonb, 2);
insert into events (id, name, category, division, icon, tagline, description, venue, event_date, event_time, team_size, fee, rules, schedule, sort_order) values ('dance-solo', 'Dance — Solo', 'Cultural', 'Dance', 'zap', 'One dancer. One stage. Infinite expression.', 'Solo dancers light up the stage with performances spanning classical, hip-hop, contemporary, and freestyle styles. A true test of individual artistry and stage presence.', 'Open-Air Stage', '16 OCT 2026', '11:00 AM', 'Individual', '₹200', '["Time limit: 5 minutes per performance.","Props allowed; fire/hazardous props prohibited.","Track must be submitted 1 hour before performance.","Costumes must be appropriate for a college event."]'::jsonb, '[{"time":"11:00 AM","activity":"Reporting"},{"time":"11:30 AM","activity":"Preliminary Round"},{"time":"01:00 PM","activity":"Lunch Break"},{"time":"02:30 PM","activity":"Final Round"},{"time":"04:30 PM","activity":"Results"}]'::jsonb, 3);
insert into events (id, name, category, division, icon, tagline, description, venue, event_date, event_time, team_size, fee, rules, schedule, sort_order) values ('dance-group', 'Dance — Group', 'Cultural', 'Dance', 'users', 'Synchronicity, energy, and collective rhythm.', 'Dance crews bring their best choreography to the stage. From cinematic themes to cultural fusion, group dance is one of the most anticipated events of COLORIDO.', 'Open-Air Stage', '17 OCT 2026', '10:00 AM', '4–12 Members', '₹1,000', '["Time limit: 8 minutes per performance.","Minimum 4 members per group.","Track must be submitted 2 hours before performance.","No hazardous props; safety is the priority."]'::jsonb, '[{"time":"10:00 AM","activity":"Reporting"},{"time":"10:30 AM","activity":"Preliminary Round"},{"time":"01:00 PM","activity":"Lunch Break"},{"time":"02:00 PM","activity":"Final Round"},{"time":"05:00 PM","activity":"Results"}]'::jsonb, 4);
insert into events (id, name, category, division, icon, tagline, description, venue, event_date, event_time, team_size, fee, rules, schedule, sort_order) values ('choreoday', 'Choreoday', 'Cultural', 'Theme Based', 'sparkles', 'A theme-based choreography championship.', 'Choreoday is a theme-based dance competition where teams build an entire performance around a central narrative. Storytelling through movement, music, and visual design.', 'Main Auditorium', '17 OCT 2026', '02:00 PM', '6–15 Members', '₹1,200', '["Theme will be announced 1 week before the event.","Time limit: 10 minutes per performance.","Minimum 6 members per team.","Props and costumes must align with the theme."]'::jsonb, '[{"time":"02:00 PM","activity":"Reporting"},{"time":"02:30 PM","activity":"Performance Round"},{"time":"05:30 PM","activity":"Results"}]'::jsonb, 5);
insert into events (id, name, category, division, icon, tagline, description, venue, event_date, event_time, team_size, fee, rules, schedule, sort_order) values ('dramatics', 'Dramatics', 'Cultural', 'Open', 'drama', 'Where stories come alive on stage.', 'A stage play competition where teams enact short plays, skits, or mime performances. Original scripts, powerful acting, and creative direction take center stage.', 'Seminar Hall', '16 OCT 2026', '02:00 PM', '4–10 Members', '₹600', '["Time limit: 15 minutes per performance.","Original scripts are encouraged.","Minimal props; focus on acting and direction.","Language: English, Telugu, or Hindi."]'::jsonb, '[{"time":"02:00 PM","activity":"Reporting"},{"time":"02:30 PM","activity":"Performance Round"},{"time":"05:30 PM","activity":"Results"}]'::jsonb, 6);
insert into events (id, name, category, division, icon, tagline, description, venue, event_date, event_time, team_size, fee, rules, schedule, sort_order) values ('fashion-show', 'Fashion Show', 'Cultural', 'Open', 'crown', 'Glamour, style, and attitude on the runway.', 'A dazzling runway competition where teams showcase themed fashion sequences. Creativity in design, confidence in walk, and overall presentation are judged.', 'Open-Air Stage', '17 OCT 2026', '04:00 PM', '6–12 Members', '₹1,000', '["Each team gets 8 minutes on the runway.","Themes: Traditional, Indo-Western, and Creative.","No offensive or inappropriate costumes.","Judges will evaluate design, walk, and presentation."]'::jsonb, '[{"time":"04:00 PM","activity":"Reporting & Backstage Setup"},{"time":"04:30 PM","activity":"Round 1 — Traditional"},{"time":"05:30 PM","activity":"Round 2 — Creative"},{"time":"06:30 PM","activity":"Results"}]'::jsonb, 7);
insert into events (id, name, category, division, icon, tagline, description, venue, event_date, event_time, team_size, fee, rules, schedule, sort_order) values ('tekraft-events', 'Tekraft Events', 'Cultural', 'Open', 'cpu', 'Where technology meets creativity.', 'A series of tech-creative events including coding challenges, UI/UX design contests, and tech quiz competitions. For the innovators and problem-solvers.', 'Computer Lab, Block C', '15 OCT 2026', '10:00 AM', 'Individual / Team of 2', '₹250', '["Coding round: 90 minutes, 3 problems.","UI/UX round: 2 hours, theme-based design.","Tech quiz: 30 questions, 30 minutes.","Internet access is restricted during coding."]'::jsonb, '[{"time":"10:00 AM","activity":"Reporting"},{"time":"10:30 AM","activity":"Coding Challenge"},{"time":"12:00 PM","activity":"Tech Quiz"},{"time":"01:00 PM","activity":"Lunch Break"},{"time":"02:00 PM","activity":"UI/UX Design Round"},{"time":"04:00 PM","activity":"Results"}]'::jsonb, 8);
insert into events (id, name, category, division, icon, tagline, description, venue, event_date, event_time, team_size, fee, rules, schedule, sort_order) values ('literary', 'Literary', 'Cultural', 'Open', 'book-open', 'Words that inspire, stories that move.', 'A literary competition featuring debate, creative writing, poetry recitation, and quiz events. For those who wield words with precision and passion.', 'Library Seminar Room', '16 OCT 2026', '10:00 AM', 'Individual', '₹150', '["Debate: 4 minutes per speaker.","Creative writing: 45 minutes, on-the-spot topic.","Poetry: original or published, 3 minutes.","Quiz: teams of 2, 30 questions."]'::jsonb, '[{"time":"10:00 AM","activity":"Reporting"},{"time":"10:30 AM","activity":"Debate Competition"},{"time":"12:00 PM","activity":"Creative Writing"},{"time":"01:00 PM","activity":"Lunch Break"},{"time":"02:00 PM","activity":"Poetry Recitation"},{"time":"03:00 PM","activity":"Literary Quiz"},{"time":"04:30 PM","activity":"Results"}]'::jsonb, 9);
insert into events (id, name, category, division, icon, tagline, description, venue, event_date, event_time, team_size, fee, rules, schedule, sort_order) values ('basketball-boys', 'Basketball', 'Sports', 'Boys', 'basketball', 'Fast breaks, sharp shooting, and team glory.', 'A high-intensity basketball tournament for boys. Teams battle through knockout rounds to claim the championship trophy.', 'College Sports Ground', '15 OCT 2026', '10:00 AM', '5 + Substitutes', '₹500', '["Each team must report 30 minutes before match time.","Matches follow standard FIBA rules.","Knockout format; single elimination.","Decisions of officials will be final."]'::jsonb, '[{"time":"10:00 AM","activity":"Team Reporting"},{"time":"10:30 AM","activity":"Match 1"},{"time":"12:00 PM","activity":"Match 2"},{"time":"02:00 PM","activity":"Semifinals"},{"time":"04:00 PM","activity":"Final"}]'::jsonb, 10);
insert into events (id, name, category, division, icon, tagline, description, venue, event_date, event_time, team_size, fee, rules, schedule, sort_order) values ('volleyball-boys', 'Volleyball', 'Sports', 'Boys', 'circle', 'Spikes, blocks, and relentless rallies.', 'A competitive volleyball tournament for boys. Teams compete in a knockout format, with each match testing skill, coordination, and endurance.', 'College Sports Ground', '16 OCT 2026', '10:00 AM', '6 + Substitutes', '₹500', '["Each team must report 30 minutes before match time.","Matches follow standard FIVB rules.","Best of 3 sets per match.","Decisions of officials will be final."]'::jsonb, '[{"time":"10:00 AM","activity":"Team Reporting"},{"time":"10:30 AM","activity":"Match 1"},{"time":"12:00 PM","activity":"Match 2"},{"time":"02:00 PM","activity":"Semifinals"},{"time":"04:00 PM","activity":"Final"}]'::jsonb, 11);
insert into events (id, name, category, division, icon, tagline, description, venue, event_date, event_time, team_size, fee, rules, schedule, sort_order) values ('table-tennis-boys', 'Table Tennis', 'Sports', 'Boys', 'circle-dot', 'Precision, speed, and razor-sharp reflexes.', 'An individual and team table tennis competition for boys. Fast-paced matches in a knockout format for singles and doubles.', 'Indoor Sports Hall', '17 OCT 2026', '10:00 AM', 'Individual / Team of 2', '₹200', '["Best of 5 games per match.","Standard ITTF rules apply.","Players must bring their own paddles.","Decisions of officials will be final."]'::jsonb, '[{"time":"10:00 AM","activity":"Reporting"},{"time":"10:30 AM","activity":"Preliminary Round"},{"time":"12:00 PM","activity":"Quarterfinals"},{"time":"02:00 PM","activity":"Semifinals"},{"time":"04:00 PM","activity":"Final"}]'::jsonb, 12);
insert into events (id, name, category, division, icon, tagline, description, venue, event_date, event_time, team_size, fee, rules, schedule, sort_order) values ('throwball-girls', 'Throwball', 'Sports', 'Girls', 'target', 'Power, placement, and team spirit.', 'A dynamic throwball tournament for girls. Teams compete with energy and coordination in a knockout format.', 'College Sports Ground', '15 OCT 2026', '10:00 AM', '7 + Substitutes', '₹500', '["Each team must report 30 minutes before match time.","Standard throwball rules apply.","Best of 3 sets per match.","Decisions of officials will be final."]'::jsonb, '[{"time":"10:00 AM","activity":"Team Reporting"},{"time":"10:30 AM","activity":"Match 1"},{"time":"12:00 PM","activity":"Match 2"},{"time":"02:00 PM","activity":"Semifinals"},{"time":"04:00 PM","activity":"Final"}]'::jsonb, 13);
insert into events (id, name, category, division, icon, tagline, description, venue, event_date, event_time, team_size, fee, rules, schedule, sort_order) values ('tennikoit-girls', 'TenniKoit', 'Sports', 'Girls', 'circle-dot', 'Agility, focus, and quick reflexes.', 'A fast-paced tennikoit (ring tennis) competition for girls. Individual and team events in a knockout format.', 'Indoor Sports Hall', '16 OCT 2026', '10:00 AM', 'Individual / Team of 2', '₹200', '["Best of 3 games per match.","Standard tennikoit rules apply.","Players must bring their own koit rings.","Decisions of officials will be final."]'::jsonb, '[{"time":"10:00 AM","activity":"Reporting"},{"time":"10:30 AM","activity":"Preliminary Round"},{"time":"12:00 PM","activity":"Quarterfinals"},{"time":"02:00 PM","activity":"Semifinals"},{"time":"04:00 PM","activity":"Final"}]'::jsonb, 14);
insert into events (id, name, category, division, icon, tagline, description, venue, event_date, event_time, team_size, fee, rules, schedule, sort_order) values ('table-tennis-girls', 'Table Tennis', 'Sports', 'Girls', 'circle-dot', 'Precision, speed, and razor-sharp reflexes.', 'An individual and team table tennis competition for girls. Fast-paced matches in a knockout format for singles and doubles.', 'Indoor Sports Hall', '17 OCT 2026', '10:00 AM', 'Individual / Team of 2', '₹200', '["Best of 5 games per match.","Standard ITTF rules apply.","Players must bring their own paddles.","Decisions of officials will be final."]'::jsonb, '[{"time":"10:00 AM","activity":"Reporting"},{"time":"10:30 AM","activity":"Preliminary Round"},{"time":"12:00 PM","activity":"Quarterfinals"},{"time":"02:00 PM","activity":"Semifinals"},{"time":"04:00 PM","activity":"Final"}]'::jsonb, 15);
